import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def adjust_due(due_date):
    if due_date.weekday() == 6:  # Sunday
        return due_date + timedelta(days=1)
    return due_date


def main():
    lines = sys.stdin.read().splitlines()
    asof_date = parse(lines[0].split(" ")[1])
    totals = {}
    for line in lines[1:]:
        if not line.strip():
            continue
        member, kind, due_text, back_text = line.split()
        due_date = parse(due_text)
        back_date = parse(back_text) if back_text != "-" else None

        adjusted_due = adjust_due(due_date)

        if back_date is None:
            days_late = (asof_date - adjusted_due).days
        else:
            days_late = (back_date - adjusted_due).days

        if days_late > 0:
            fee = max(days_late - 3, 0) * RATE[kind]
            totals[member] = totals.get(member, 0) + fee
    for member in sorted(totals):
        print(f"{member} {totals[member]:.2f}")
    total_fee = sum(totals.values())
    print(f"total {total_fee:.2f}")


if __name__ == "__main__":
    main()
